from pathlib import Path


def replace_once(text: str, old: str, new: str) -> str:
    if old not in text:
        raise SystemExit(f'patch anchor missing: {old[:100]!r}')
    return text.replace(old, new, 1)


# Seed adapter: optional strict binding to a predeclared plan.
path = Path('tools/build_development_generalization_seed.py')
text = path.read_text(encoding='utf-8')
text = replace_once(text, 'import argparse\nimport json\nimport pathlib\n', 'import argparse\nimport hashlib\nimport json\nimport pathlib\n')
text = replace_once(text, 'SEED_CLASS = "development-generalization-seed-v1"\nROBUSTNESS_CLASS', 'SEED_CLASS = "development-generalization-seed-v1"\nPLAN_CLASS = "development-generalization-plan-v1"\nPLAN_POLICY = "development-generalization-v1"\nROBUSTNESS_CLASS')
anchor = '''def non_negative_int(value: object, label: str) -> int:\n'''
insert = '''def plan_sha256(value: dict) -> str:\n    if int(value.get("schema_version", 0)) != 1 or value.get("evidence_class") != PLAN_CLASS:\n        raise ValueError("generalization plan identity mismatch")\n    if value.get("policy") != PLAN_POLICY or value.get("evidence_scope") != "development-only":\n        raise ValueError("generalization plan policy/scope mismatch")\n    for key in ("fresh_used", "shadow_used", "formal_qualification_used"):\n        if value.get(key) is not False:\n            raise ValueError(f"generalization plan protected flag {key} must be false")\n    if value.get("selection_before_results") is not True:\n        raise ValueError("generalization plan must be selected before results")\n    expected = value.get("plan_sha256")\n    if not isinstance(expected, str) or len(expected) != 64:\n        raise ValueError("generalization plan_sha256 is invalid")\n    body = dict(value)\n    body.pop("plan_sha256", None)\n    raw = json.dumps(body, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")\n    actual = hashlib.sha256(raw).hexdigest()\n    if actual != expected:\n        raise ValueError("generalization plan_sha256 mismatch")\n    return actual\n\n\ndef bind_plan(\n    *,\n    plan: dict,\n    ordinal: int,\n    tier: str,\n    model_family: str,\n    candidate_id: str,\n    source_identity: str,\n    seed: int,\n) -> dict:\n    digest = plan_sha256(plan)\n    if plan.get("tier") != tier or plan.get("model_family") != model_family or plan.get("candidate_id") != candidate_id:\n        raise ValueError("generalization plan tier/family/candidate mismatch")\n    entries = plan.get("seed_plan")\n    if not isinstance(entries, list) or int(plan.get("independent_seed_count", -1)) != len(entries):\n        raise ValueError("generalization plan seed cohort is invalid")\n    ordinal = int(ordinal)\n    if ordinal < 0 or ordinal >= len(entries):\n        raise ValueError("generalization plan ordinal is out of range")\n    entry = entries[ordinal]\n    if not isinstance(entry, dict) or int(entry.get("ordinal", -1)) != ordinal:\n        raise ValueError("generalization plan ordinal identity mismatch")\n    if int(entry.get("seed", -1)) != seed or str(entry.get("source_identity", "")) != source_identity:\n        raise ValueError("generalization seed/source does not match predeclared plan")\n    return {\n        "plan_sha256": digest,\n        "plan_ordinal": ordinal,\n        "plan_model_sha256": str(plan.get("model_sha256", "")),\n        "plan_product_head": str(plan.get("product_head", "")),\n    }\n\n\n'''
text = replace_once(text, anchor, insert + anchor)
text = replace_once(text, '''    source_identity: str,\n    seed: int,\n) -> dict:\n''', '''    source_identity: str,\n    seed: int,\n    plan: dict | None = None,\n    plan_ordinal: int | None = None,\n) -> dict:\n''')
text = replace_once(text, '''    seed = non_negative_int(seed, "seed")\n\n    overall = domain_metrics.get("overall")\n''', '''    seed = non_negative_int(seed, "seed")\n    if (plan is None) != (plan_ordinal is None):\n        raise ValueError("plan and plan_ordinal must be supplied together")\n    plan_binding = {}\n    if plan is not None and plan_ordinal is not None:\n        plan_binding = bind_plan(\n            plan=plan, ordinal=plan_ordinal, tier=tier, model_family=model_family,\n            candidate_id=candidate_id, source_identity=source_identity, seed=seed,\n        )\n\n    overall = domain_metrics.get("overall")\n''')
text = replace_once(text, '''        "seed": seed,\n        "expected_wakes": expected,\n''', '''        "seed": seed,\n        **plan_binding,\n        "expected_wakes": expected,\n''')
text = replace_once(text, '''    parser.add_argument("--seed", required=True, type=int)\n    parser.add_argument("--output", required=True, type=pathlib.Path)\n''', '''    parser.add_argument("--seed", required=True, type=int)\n    parser.add_argument("--plan", type=pathlib.Path)\n    parser.add_argument("--plan-ordinal", type=int)\n    parser.add_argument("--output", required=True, type=pathlib.Path)\n''')
text = replace_once(text, '''    result = build_seed(\n        domain_metrics=load_object(args.domain_metrics),\n''', '''    plan = load_object(args.plan.resolve()) if args.plan is not None else None\n    result = build_seed(\n        domain_metrics=load_object(args.domain_metrics),\n''')
text = replace_once(text, '''        source_identity=args.source_identity,\n        seed=args.seed,\n    )\n''', '''        source_identity=args.source_identity,\n        seed=args.seed,\n        plan=plan,\n        plan_ordinal=args.plan_ordinal,\n    )\n''')
path.write_text(text, encoding='utf-8')

# Aggregator: when a plan is supplied, require the exact complete cohort.
path = Path('tools/development_generalization.py')
text = path.read_text(encoding='utf-8')
text = replace_once(text, 'import argparse\nimport json\nimport math\n', 'import argparse\nimport hashlib\nimport json\nimport math\n')
text = replace_once(text, 'REPORT_EVIDENCE_CLASS = "development-generalization-report-v1"\n', 'REPORT_EVIDENCE_CLASS = "development-generalization-report-v1"\nPLAN_EVIDENCE_CLASS = "development-generalization-plan-v1"\n')
anchor = '''def _non_negative_int(value: object, label: str) -> int:\n'''
insert = '''def _plan_sha256(value: dict) -> str:\n    if int(value.get("schema_version", 0)) != 1 or value.get("evidence_class") != PLAN_EVIDENCE_CLASS:\n        raise ValueError("generalization plan identity mismatch")\n    if value.get("policy") != POLICY or value.get("evidence_scope") != "development-only":\n        raise ValueError("generalization plan policy/scope mismatch")\n    for key in ("fresh_used", "shadow_used", "formal_qualification_used"):\n        if value.get(key) is not False:\n            raise ValueError(f"generalization plan protected flag {key} must be false")\n    if value.get("selection_before_results") is not True:\n        raise ValueError("generalization plan must be selected before results")\n    expected = value.get("plan_sha256")\n    if not isinstance(expected, str) or len(expected) != 64:\n        raise ValueError("generalization plan_sha256 is invalid")\n    body = dict(value)\n    body.pop("plan_sha256", None)\n    raw = json.dumps(body, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")\n    actual = hashlib.sha256(raw).hexdigest()\n    if actual != expected:\n        raise ValueError("generalization plan_sha256 mismatch")\n    return actual\n\n\n'''
text = replace_once(text, anchor, insert + anchor)
text = replace_once(text, '''    return {\n        "path": path.as_posix(),\n''', '''    plan_sha = value.get("plan_sha256")\n    plan_ordinal = value.get("plan_ordinal")\n    if (plan_sha is None) != (plan_ordinal is None):\n        raise ValueError(f"{path}: incomplete plan binding")\n    if plan_sha is not None:\n        if not isinstance(plan_sha, str) or len(plan_sha) != 64:\n            raise ValueError(f"{path}: invalid plan_sha256")\n        plan_ordinal = _non_negative_int(plan_ordinal, f"{path}.plan_ordinal")\n\n    return {\n        "path": path.as_posix(),\n''')
text = replace_once(text, '''        "seed": seed,\n        "expected_wakes": expected,\n''', '''        "seed": seed,\n        "plan_sha256": plan_sha,\n        "plan_ordinal": plan_ordinal,\n        "expected_wakes": expected,\n''')
text = replace_once(text, '''def build_report(policy: dict, tier: str, seed_paths: list[pathlib.Path]) -> dict:\n''', '''def build_report(policy: dict, tier: str, seed_paths: list[pathlib.Path], plan: dict | None = None) -> dict:\n''')
text = replace_once(text, '''    if len(set(sources)) != len(sources):\n        raise ValueError("generalization source identities must be unique")\n\n    expected = sum(item["expected_wakes"] for item in seeds)\n''', '''    if len(set(sources)) != len(sources):\n        raise ValueError("generalization source identities must be unique")\n\n    plan_binding = {}\n    if plan is not None:\n        digest = _plan_sha256(plan)\n        if plan.get("tier") != tier or plan.get("model_family") != next(iter(families)) or plan.get("candidate_id") != next(iter(candidates)):\n            raise ValueError("generalization plan tier/family/candidate mismatch")\n        entries = plan.get("seed_plan")\n        if not isinstance(entries, list) or int(plan.get("independent_seed_count", -1)) != len(entries):\n            raise ValueError("generalization plan seed cohort is invalid")\n        if len(seeds) != len(entries):\n            raise ValueError("generalization report requires the complete predeclared seed cohort")\n        by_ordinal = {}\n        for item in seeds:\n            if item["plan_sha256"] != digest or item["plan_ordinal"] is None:\n                raise ValueError("seed summary is not bound to the supplied plan")\n            ordinal = int(item["plan_ordinal"])
            if ordinal in by_ordinal:\n                raise ValueError("duplicate generalization plan ordinal")\n            by_ordinal[ordinal] = item\n        if set(by_ordinal) != set(range(len(entries))):\n            raise ValueError("generalization plan ordinals are incomplete")\n        for ordinal, entry in enumerate(entries):\n            if int(entry.get("ordinal", -1)) != ordinal:\n                raise ValueError("generalization plan ordinal identity mismatch")\n            item = by_ordinal[ordinal]\n            if item["seed"] != int(entry.get("seed", -1)) or item["source_identity"] != str(entry.get("source_identity", "")):\n                raise ValueError("seed summary does not match its predeclared plan entry")\n        plan_binding = {"plan_sha256": digest, "plan_complete": True}\n\n    expected = sum(item["expected_wakes"] for item in seeds)\n''')
text = replace_once(text, '''        "candidate_id": next(iter(candidates)),\n        "independent_seed_count": len(seeds),\n''', '''        "candidate_id": next(iter(candidates)),\n        **plan_binding,\n        "independent_seed_count": len(seeds),\n''')
text = replace_once(text, '''    parser.add_argument("--seed-summary", required=True, action="append", type=pathlib.Path)\n    parser.add_argument("--output", required=True, type=pathlib.Path)\n''', '''    parser.add_argument("--seed-summary", required=True, action="append", type=pathlib.Path)\n    parser.add_argument("--plan", type=pathlib.Path)\n    parser.add_argument("--output", required=True, type=pathlib.Path)\n''')
text = replace_once(text, '''    report = build_report(policy, args.tier, [path.resolve() for path in args.seed_summary])\n''', '''    plan = _load_object(args.plan.resolve()) if args.plan is not None else None\n    report = build_report(policy, args.tier, [path.resolve() for path in args.seed_summary], plan=plan)\n''')
path.write_text(text, encoding='utf-8')
